"""
lab_bank.py — Ngân hàng Hóa chất (mô hình 3D) & Phản ứng cho Lab 3D.
=====================================================================
Trước đây toàn bộ ~13 phân tử có toạ độ nguyên tử/liên kết 3D (LAB_MOLECULE_DATA,
dùng cho tính năng "Phân tích cấu trúc phân tử 3D") và ~233 phản ứng hoá học tĩnh
(REACTIONS, dùng cho Random Task / hiển thị phản ứng trong lab) đều nằm CỨNG
trong lab.html — admin không thể thêm/sửa/xoá, và mọi thay đổi phải sửa trực
tiếp file JS khổng lồ.

Module này lưu 3 ngân hàng vào Firestore (KHÔNG phải SQLite — đây là NỘI DUNG
admin biên tập: hoá chất, phản ứng, chai hoá chất trên kệ, cần sống sót qua
các lần Render restart/redeploy, không chỉ là dữ liệu tracking tạm thời):
  - lab_molecules        (collection `lab_molecules_bank`) : hoá chất có mô
    hình 3D (atoms/bonds), dùng cho tính năng xem cấu trúc phân tử.
  - lab_reactions         (collection `lab_reactions_bank`) : phản ứng hoá
    học (phương trình, điều kiện, hiện tượng...).
  - lab_shelf_chemicals   (collection `lab_shelf_chemicals_bank`) : hoá chất
    thật trên kệ Lab 3D mà học sinh chọn để pha trộn (~163 chất).

Mỗi bản ghi có trường `status` ('draft' | 'published'):
  - 'draft'     : admin đang soạn/thử nghiệm, CHƯA hiển thị cho học sinh.
  - 'published' : hiển thị đầy đủ trong lab.html cho học sinh sử dụng.

seed_default_*() chạy 1 lần lúc khởi động server, chỉ insert dữ liệu gốc
(di trú từ lab.html) NẾU collection đang trống, để không mất/không lặp dữ
liệu cũ — toàn bộ đều seed với status='published' vì đây là dữ liệu đã được
kiểm chứng, dùng trong lab từ trước.

Lưu ý: ~9 phản ứng "khuôn mẫu" trong REACTIONS gốc (chứa cú pháp ${...} như
${oaPretty} + ${b.pretty} → ${salt} + H₂O) là các mẫu được lab.html tự động
điền giá trị lúc chạy (kết hợp oxit/axit/bazơ/kim loại ngẫu nhiên) — KHÔNG
phải phản ứng tĩnh nên không di trú vào đây; cơ chế sinh phản ứng tổ hợp đó
vẫn giữ nguyên trong lab.html.
"""
import json
import time

import firestore_db as fsdb

_MOLECULES_COL = 'lab_molecules_bank'
_REACTIONS_COL = 'lab_reactions_bank'
_SHELF_COL = 'lab_shelf_chemicals_bank'


def _doc_to_molecule(doc) -> dict:
    d = doc.to_dict()
    return {
        'id': doc.id,
        'chemId': d.get('chem_id', ''),
        'name': d.get('name', ''),
        'formula': d.get('formula', ''),
        'molWeight': d.get('mol_weight'),
        'polar': bool(d.get('polar')),
        'bondAngle': d.get('bond_angle'),
        'bondsDesc': d.get('bonds_desc', ''),
        'desc': d.get('desc', ''),
        'atoms': d.get('atoms', []),
        'bonds': d.get('bonds', []),
        'status': d.get('status', 'draft'),
        'createdBy': d.get('created_by', ''),
        'createdAt': d.get('created_at'),
        'updatedAt': d.get('updated_at'),
    }


def _doc_to_reaction(doc) -> dict:
    d = doc.to_dict()
    return {
        'id': doc.id,
        'eq': d.get('eq', ''),
        'type': d.get('type', ''),
        'conditions': d.get('conditions', ''),
        'tools': d.get('tools', ''),
        'steps': d.get('steps', ''),
        'obs': d.get('obs', ''),
        'product': d.get('product', ''),
        'grp': d.get('grp', ''),
        'participants': d.get('participants', []),
        'needsHeat': bool(d.get('needs_heat')),
        'beforeColor': d.get('before_color', '#ffffff'),
        'beforePhenomenon': d.get('before_phenomenon', ''),
        'duringColor': d.get('during_color', '#ffffff'),
        'duringPhenomenon': d.get('during_phenomenon', ''),
        'afterColor': d.get('after_color', '#ffffff'),
        'afterPhenomenon': d.get('after_phenomenon', ''),
        'premiumOnly': bool(d.get('premium_only')),
        'status': d.get('status', 'draft'),
        'createdBy': d.get('created_by', ''),
        'createdAt': d.get('created_at'),
        'updatedAt': d.get('updated_at'),
    }


