def seed_default_molecules() -> int:
    items = json.loads(_SEED_MOLECULES_JSON)
    ts = time.time()
    docs = {}
    for it in items:
        docs[it['id']] = {
            'chem_id': it['id'], 'name': it.get('name', ''), 'formula': it.get('formula', ''),
            'mol_weight': it.get('molWeight'), 'polar': bool(it.get('polar')),
            'bond_angle': it.get('bondAngle'), 'bonds_desc': it.get('bonds_desc', ''),
            'desc': it.get('desc', ''), 'atoms': it.get('atoms', []), 'bonds': it.get('bonds', []),
            'status': 'published', 'created_by': 'system_seed', 'created_at': ts, 'updated_at': ts,
        }
    return fsdb.batched_seed(_MOLECULES_COL, docs)


def seed_default_reactions() -> int:
    items = json.loads(_SEED_REACTIONS_JSON)
    ts = time.time()
    docs = {}
    for i, it in enumerate(items):
        docs[f'seed_{i:03d}'] = {
            'eq': it.get('eq', ''), 'type': it.get('type', ''), 'conditions': it.get('conditions', ''),
            'tools': it.get('tools', ''), 'steps': it.get('steps', ''), 'obs': it.get('obs', ''),
            'product': it.get('product', ''), 'grp': it.get('grp', ''), 'participants': [],
            'needs_heat': False, 'before_color': '#ffffff', 'before_phenomenon': '',
            'during_color': '#ffffff', 'during_phenomenon': '', 'after_color': '#ffffff',
            'after_phenomenon': '', 'status': 'published', 'created_by': 'system_seed',
            'created_at': ts, 'updated_at': ts,
        }
    return fsdb.batched_seed(_REACTIONS_COL, docs)


# ── Molecules CRUD ─────────────────────────────────────────────────────────
def filter_premium_only(items: list[dict], unlimited: bool) -> list[dict]:
    """Lọc bỏ các hoá chất/phản ứng đánh dấu `premiumOnly` khỏi danh sách trả
    về cho học sinh KHÔNG có Premium (#6 — Mở khóa nội dung Lab 3D/công thức
    nâng cao chỉ dành cho Premium). An toàn theo mặc định: nếu không xác
    định được `unlimited` (VD khách vãng lai chưa đăng nhập), coi như KHÔNG
    có Premium — chỉ ẩn, không lộ nội dung nâng cao."""
    if unlimited:
        return items
    return [it for it in items if not it.get('premiumOnly')]


def list_molecules(status: str = None) -> list[dict]:
    col = fsdb.collection(_MOLECULES_COL)
    q = col.where('status', '==', status) if status else col
    items = [_doc_to_molecule(d) for d in q.stream()]
    items.sort(key=lambda x: x.get('createdAt') or 0, reverse=True)
    return items


def get_molecule(mid: str) -> dict | None:
    doc = fsdb.collection(_MOLECULES_COL).document(str(mid)).get()
    return _doc_to_molecule(doc) if doc.exists else None


def create_molecule(chem_id: str, name: str, formula: str, atoms: list, bonds: list,
                     mol_weight: float = None, polar: bool = False, bond_angle: float = None,
                     bonds_desc: str = '', desc: str = '', status: str = 'draft',
                     created_by: str = '') -> str:
    ts = time.time()
    ref = fsdb.collection(_MOLECULES_COL).document()
    ref.set({
        'chem_id': chem_id, 'name': name, 'formula': formula, 'mol_weight': mol_weight,
        'polar': bool(polar), 'bond_angle': bond_angle, 'bonds_desc': bonds_desc, 'desc': desc,
        'atoms': atoms, 'bonds': bonds, 'status': status, 'created_by': created_by,
        'created_at': ts, 'updated_at': ts,
    })
    return ref.id


def update_molecule(mid: str, **fields) -> bool:
    ref = fsdb.collection(_MOLECULES_COL).document(str(mid))
    if not ref.get().exists:
        return False
    mapping = {
        'chemId': 'chem_id', 'name': 'name', 'formula': 'formula', 'molWeight': 'mol_weight',
        'polar': 'polar', 'bondAngle': 'bond_angle', 'bondsDesc': 'bonds_desc', 'desc': 'desc',
        'atoms': 'atoms', 'bonds': 'bonds', 'status': 'status',
    }
    updates = {}
    for key, col_name in mapping.items():
        if key in fields and fields[key] is not None:
            v = fields[key]
            if key == 'polar':
                v = bool(v)
            updates[col_name] = v
    if not updates:
        return True
    updates['updated_at'] = time.time()
    ref.update(updates)
    return True


def delete_molecule(mid: str) -> bool:
    ref = fsdb.collection(_MOLECULES_COL).document(str(mid))
    if not ref.get().exists:
        return False
    ref.delete()
    return True


# ── Reactions CRUD ──────────────────────────────────────────────────────────
def list_reactions(status: str = None) -> list[dict]:
    col = fsdb.collection(_REACTIONS_COL)
    q = col.where('status', '==', status) if status else col
    items = [_doc_to_reaction(d) for d in q.stream()]
    items.sort(key=lambda x: x.get('createdAt') or 0, reverse=True)
    return items


def get_reaction(rid: str) -> dict | None:
    doc = fsdb.collection(_REACTIONS_COL).document(str(rid)).get()
    return _doc_to_reaction(doc) if doc.exists else None


def create_reaction(eq: str, type_: str = '', conditions: str = '', tools: str = '',
                     steps: str = '', obs: str = '', product: str = '', grp: str = '',
                     participants: list = None, needs_heat: bool = False,
                     before_color: str = '#ffffff', before_phenomenon: str = '',
                     during_color: str = '#ffffff', during_phenomenon: str = '',
                     after_color: str = '#ffffff', after_phenomenon: str = '',
                     status: str = 'draft', created_by: str = '', premium_only: bool = False) -> str:
    ts = time.time()
    ref = fsdb.collection(_REACTIONS_COL).document()
    ref.set({
        'eq': eq, 'type': type_, 'conditions': conditions, 'tools': tools, 'steps': steps,
        'obs': obs, 'product': product, 'grp': grp, 'participants': participants or [],
        'needs_heat': bool(needs_heat), 'before_color': before_color,
        'before_phenomenon': before_phenomenon, 'during_color': during_color,
        'during_phenomenon': during_phenomenon, 'after_color': after_color,
        'after_phenomenon': after_phenomenon, 'premium_only': bool(premium_only),
        'status': status, 'created_by': created_by,
        'created_at': ts, 'updated_at': ts,
    })
    return ref.id


def update_reaction(rid: str, **fields) -> bool:
    ref = fsdb.collection(_REACTIONS_COL).document(str(rid))
    if not ref.get().exists:
        return False
    mapping = {
        'eq': 'eq', 'type': 'type', 'conditions': 'conditions', 'tools': 'tools',
        'steps': 'steps', 'obs': 'obs', 'product': 'product', 'grp': 'grp', 'status': 'status',
        'participants': 'participants', 'needsHeat': 'needs_heat',
        'beforeColor': 'before_color', 'beforePhenomenon': 'before_phenomenon',
        'duringColor': 'during_color', 'duringPhenomenon': 'during_phenomenon',
        'afterColor': 'after_color', 'afterPhenomenon': 'after_phenomenon',
        'premiumOnly': 'premium_only',
    }
    updates = {}
    for key, col_name in mapping.items():
        if key in fields and fields[key] is not None:
            v = fields[key]
            if key in ('needsHeat', 'premiumOnly'):
                v = bool(v)
            updates[col_name] = v
    if not updates:
        return True
    updates['updated_at'] = time.time()
    ref.update(updates)
    return True


def delete_reaction(rid: str) -> bool:
    ref = fsdb.collection(_REACTIONS_COL).document(str(rid))
    if not ref.get().exists:
        return False
    ref.delete()
    return True


