def _doc_to_shelf_chemical(doc) -> dict:
    d = doc.to_dict()
    return {
        'id': doc.id,
        'chemId': d.get('chem_id', ''),
        'name': d.get('name', ''),
        'desc': d.get('desc', ''),
        'type': d.get('type', ''),
        'cat': d.get('cat', ''),
        'color': d.get('color', '#ffffff'),
        'ph': d.get('ph'),
        'solid': bool(d.get('solid')),
        'isGas': bool(d.get('is_gas')),
        'isPaper': bool(d.get('is_paper')),
        'opacity': d.get('opacity'),
        'allowedStates': d.get('allowed_states', []),
        'premiumOnly': bool(d.get('premium_only')),
        'status': d.get('status', 'draft'),
        'createdBy': d.get('created_by', ''),
        'createdAt': d.get('created_at'),
        'updatedAt': d.get('updated_at'),
    }


def seed_default_shelf_chemicals() -> int:
    items = json.loads(_SEED_SHELF_CHEMICALS_JSON)
    ts = time.time()
    docs = {}
    for it in items:
        docs[it['id']] = {
            'chem_id': it['id'], 'name': it.get('name', it['id']), 'desc': it.get('desc', ''),
            'type': it.get('type', ''), 'cat': it.get('cat', 'voco'), 'color': it.get('color', '#ffffff'),
            'ph': it.get('ph'), 'solid': bool(it.get('solid')), 'is_gas': bool(it.get('isGas')),
            'is_paper': bool(it.get('isPaper')), 'opacity': it.get('op'),
            'allowed_states': it.get('allowedStates', []), 'status': 'published',
            'created_by': 'system_seed', 'created_at': ts, 'updated_at': ts,
        }
    return fsdb.batched_seed(_SHELF_COL, docs)


def list_shelf_chemicals(status: str = None) -> list[dict]:
    col = fsdb.collection(_SHELF_COL)
    q = col.where('status', '==', status) if status else col
    items = [_doc_to_shelf_chemical(d) for d in q.stream()]
    items.sort(key=lambda x: x.get('createdAt') or 0, reverse=True)
    return items


def get_shelf_chemical(sid: str) -> dict | None:
    doc = fsdb.collection(_SHELF_COL).document(str(sid)).get()
    return _doc_to_shelf_chemical(doc) if doc.exists else None


def create_shelf_chemical(chem_id: str, name: str, cat: str, desc: str = '', type_: str = '',
                           color: str = '#ffffff', ph=None, solid: bool = False, is_gas: bool = False,
                           is_paper: bool = False, opacity=None, allowed_states: list = None,
                           status: str = 'draft', created_by: str = '', premium_only: bool = False) -> str:
    ts = time.time()
    ref = fsdb.collection(_SHELF_COL).document()
    ref.set({
        'chem_id': chem_id, 'name': name, 'desc': desc, 'type': type_, 'cat': cat, 'color': color,
        'ph': ph, 'solid': bool(solid), 'is_gas': bool(is_gas), 'is_paper': bool(is_paper),
        'opacity': opacity, 'allowed_states': allowed_states or [], 'premium_only': bool(premium_only),
        'status': status, 'created_by': created_by, 'created_at': ts, 'updated_at': ts,
    })
    return ref.id


def update_shelf_chemical(sid: str, **fields) -> bool:
    ref = fsdb.collection(_SHELF_COL).document(str(sid))
    if not ref.get().exists:
        return False
    mapping = {
        'chemId': 'chem_id', 'name': 'name', 'desc': 'desc', 'type': 'type', 'cat': 'cat',
        'color': 'color', 'ph': 'ph', 'solid': 'solid', 'isGas': 'is_gas', 'isPaper': 'is_paper',
        'opacity': 'opacity', 'allowedStates': 'allowed_states', 'status': 'status',
        'premiumOnly': 'premium_only',
    }
    updates = {}
    for key, col_name in mapping.items():
        if key in fields and fields[key] is not None:
            v = fields[key]
            if key in ('solid', 'isGas', 'isPaper', 'premiumOnly'):
                v = bool(v)
            updates[col_name] = v
    if not updates:
        return True
    updates['updated_at'] = time.time()
    ref.update(updates)
    return True


def delete_shelf_chemical(sid: str) -> bool:
    ref = fsdb.collection(_SHELF_COL).document(str(sid))
    if not ref.get().exists:
        return False
    ref.delete()
    return True
